import subprocess,os,sys,json
SESS='session_2026-11-06-pipeline-batch'
DB=os.path.abspath('scratchpad/session_2026-11-06-pipeline-batch/walk.db')
R='retrieval-log/'+SESS
ENV={**os.environ,'GUIDEBOOK_DB_PATH':DB}
def db(*a):
    o=subprocess.run(['python3','scripts/db.py',*a],env=ENV,capture_output=True,text=True)
    out=(o.stdout+o.stderr)
    bad='REFUS' in out or o.returncode!=0
    print(('FAIL ' if bad else 'ok   ')+a[0], ' | '.join(l.strip() for l in out.splitlines() if 'REFUS' in l or '_id"' in l)[:300]); 
    if bad: print(out[-600:]); sys.exit(1)
    return out
