def cand(title,pm,tier,notes):
    db('add-candidate','--exec-id','200','--disposition','PENDING-VERIFICATION','--title',title,'--locator',f'https://pubmed.ncbi.nlm.nih.gov/{pm}/','--tier-guess',str(tier),'--notes',notes,'--surfaced-in',F,'--surfaced-quote',pm,'--session',SESS)
cand("Higuchi, Hatano, Soma and Imanaka 2009, Perception of spatial requirements for wheelchair locomotion in experienced users with tetraplegia (J Physiol Anthropol 28:15)",'19212090',3,'HYPOTHESIS from the abstract only (DOI 10.2114/jpa2.28.15): tetraplegic wheelchair users and able-bodied controls judged whether a doorway width was passable in familiar and unfamiliar wheelchairs; reports the ratio of the perceptual boundary to the minimum passable width. Participants are people with tetraplegia, the population a wheelchair door width serves. Experimental perception study, so the tier guess is 3 pending the design read. Full text not sought.')
cand("Paquet, Joseph and D'Souza 2012, Computer re-sampling for demographically representative user populations in anthropometry: a case of doorway and clear floor space widths (Work)",'22317349',3,'HYPOTHESIS from the abstract only (DOI 10.3233/WOR-2012-0703-4098): a sampling-method paper that uses door width and clear floor space width as its worked example. The abstract states no width figure; whether it reports a door width a person needs is unknown until the full text is read.')
cand('Savelsbergh, Douwes Dekker, Vermeer and Hopkins 1998, Locomoting through apertures of different width: a study of children with cerebral palsy (Pediatr Rehabil)','9661706',3,'HYPOTHESIS from the abstract only (DOI 10.3109/17518429809078610): 55 children, 23 non-handicapped and 32 with cerebral palsy (12 walking, 20 in wheelchairs), judged and attempted passage through apertures of varying width. Children, so a PROXY for the adults a door width serves (R13).')
